import { Injectable } from '@angular/core';
import { Storage } from '@ionic/storage';
import { Observable, BehaviorSubject, of } from 'rxjs';


@Injectable({
  providedIn: 'root'
})
export class IonicStorageService {

  inserData = new BehaviorSubject(false);
  exitsData = new BehaviorSubject(false);
  constructor(private storage: Storage) {
  }
  insertData_Replace(key, data): Observable<any> {
    this.storage.set(key, data).then(r => {
      this.inserData.next(true);
    });
    return of(this.inserData.asObservable());
  }
  insertData_noReplace(key, data): Observable<any> {

    this.getData(key).then(res => {
      let temp = []
      if (res) {
        temp = res
        temp.push(data)
      } else {
        temp = [data]
      }
      this.storage.set(key, temp).then(r => {
        this.inserData.next(true);
      });
    });

    return of(this.inserData.asObservable());
  }

  studentSave_noReplace(key, data, clList): Observable<any> {
    let status = false;
    this.getData(key).then(res => {
      let temp = []

      if (res != null && res.length !== 0) {
        let i = 0;
        for (let val of res) {
          if (val[clList.class_id + '-' + clList.section] !== undefined) {
            res[i] = data;
            temp = res;
            status = false;
            break;
          } else {
            status = true;
          }
          i++;
        }
        if (status) {
          res.push(data);
          temp = res;
        }
      } else {
        temp = [data];
      }
      this.storage.set(key, temp).then(r => {
        // console.log(83, r);
        this.inserData.next(true);
      });
    });

    return of(this.inserData.asObservable());
  }
  getData(key) {

    return this.storage.get(key);
  }
  removeKey(key) {
    return this.storage.remove(key);
  }

  loopData(key) {
    return this.storage.forEach(key);
  }



  isKeyAvabile(key) {

    return this.storage.keys();
  }


}
