  async presentAlertConfirmExit(message) {
    const alert = await this.alertController.create({
      header: message + ' Confirmation',
      message: 'Do you want to ' + message + ' App?',
      buttons: [
        {
          text: 'Cancel',
          role: 'cancel',
          cssClass: 'primary',
          handler: () => {
          }
        }, {
          text: 'Yes',
          handler: () => {
            if (message === 'Exit') {              
              navigator['app'].exitApp();
            } else {
              this.router.navigate(['login']);
            }
          }
        }
      ]
    });
    await alert.present();
  }


