export class AppModule {
  private readonly studentList: string = 'https://ndr5aolnkzgpnmxswzn54yvpta.appsync-api.ap-south-1.amazonaws.com/graphql';
  private readonly studentStatus: string = 'https://yql6g6rzr5gjhdn5xy562pytsu.appsync-api.ap-south-1.amazonaws.com/graphql';

  private readonly itkstudentList: string ='https://2bdg3nn2yjdurk3mxoswhhpiwq.appsync-api.ap-south-1.amazonaws.com/graphql';
  private readonly itkstudentStatus: string = 'https://wb4rm55jfff55k4kwl56m7ra7u.appsync-api.ap-south-1.amazonaws.com/graphql';
  
  constructor(  apollo: Apollo,
    httpLink: HttpLink
  ) {
    const options1: any = { uri: this.studentList };
    apollo.createDefault({
      link: saveStudentListLink.concat(httpLink.create(options1)),
      cache: new InMemoryCache()
    });
  
    const options2: any = { uri: this.studentStatus };
    apollo.createNamed('endpoint2', {
      link: saveStudentStatusLink.concat(httpLink.create(options2)),
      cache: new InMemoryCache()
    });

    const options3: any = { uri: this.itkstudentList };
    apollo.createNamed('endpoint3', {
      link: saveITKStudentListLink.concat(httpLink.create(options3)),
      cache: new InMemoryCache()
    });

    const options4: any = { uri: this.itkstudentStatus };
    apollo.createNamed('endpoint4', {
      link: saveITKStudentStatusLink.concat(httpLink.create(options4)),
      cache: new InMemoryCache()
    });
  }
 }
